<?php require_once __DIR__.'/config/database.php';if($_SERVER['REQUEST_METHOD']!=='POST'){redirect('index.php');}csrf_check();$email=strtolower(trim($_POST['email']??''));if(!filter_var($email,FILTER_VALIDATE_EMAIL)){flash('error','Please enter a valid email address.');}else{try{$s=$pdo->prepare('INSERT INTO newsletter(email) VALUES(?)');$s->execute([$email]);flash('success','Thank you. A little lumière will find its way to your inbox.');}catch(PDOException $e){flash('success','You are already on our list. Thank you.');}}redirect('index.php');
